-- Minimal existing schema for local PostgreSQL behavioral validation.
create role authenticated;
create role anon;
create schema auth;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth,public to authenticated,anon;
grant execute on function auth.uid() to authenticated,anon;
create table stores(id uuid primary key,is_active boolean default true);
create table profiles(id uuid primary key references auth.users,store_id uuid references stores,role text);
grant select on profiles,stores to authenticated;
create table common_inventory_names(id uuid primary key default gen_random_uuid(),common_name text unique not null,category text,default_unit text,is_active boolean default true,created_at timestamptz default now());
create table inventory_items(id uuid primary key default gen_random_uuid(),item_name text not null,common_name text,common_name_id uuid references common_inventory_names,category text,unit text not null,current_stock numeric(14,3) default 0,is_active boolean default true,updated_at timestamptz default now(),normalized_common_name text generated always as(lower(regexp_replace(trim(common_name),'\s+',' ','g'))) stored);
create unique index unique_active_common on inventory_items(normalized_common_name) where is_active is true;
alter table inventory_items enable row level security;
create policy staff_inventory_select on inventory_items for select to authenticated using(true);
grant select on inventory_items,common_inventory_names to authenticated;
create table finance_expenses(id text primary key,expense_date date,inventory_item_id uuid,quantity numeric,unit text,store_id text,petty_cash_entry_id text,total numeric);
create table finance_petty_cash_entries(id text primary key,expense_date date,inventory_item_id uuid,quantity numeric,unit text,store_id uuid,total numeric);
create table expense_inventory_links(id uuid primary key default gen_random_uuid(),expense_id text,inventory_item_id uuid,purchased_quantity numeric,purchased_unit text);
create table inventory_transactions(id uuid primary key default gen_random_uuid(),inventory_item_id uuid,common_name_id uuid,transaction_type text,quantity numeric,unit text,quantity_effect numeric,reference_type text,reference_id text,notes text,created_by uuid,created_at timestamptz default now());
create table stock_movements(id uuid primary key default gen_random_uuid(),inventory_item_id uuid,stock_item_id uuid,movement_type text,type text,quantity numeric,unit text,source_type text,source_id text,ref_entity text,ref_id text,notes text,created_by uuid,created_at timestamptz default now());
grant select on inventory_transactions,stock_movements to authenticated;
create table finance_daily_inventory_entries(id uuid primary key default gen_random_uuid(),inventory_date date,store_id uuid,inventory_item_id uuid,beginning_quantity numeric(14,3) default 0,reorder_quantity numeric(14,3) default 0,manual_adjustment_quantity numeric(14,3) default 0,ending_quantity numeric(14,3) default 0,created_by uuid,updated_by uuid,unique(inventory_date,store_id,inventory_item_id));
alter table finance_daily_inventory_entries enable row level security;
create policy cashier_daily on finance_daily_inventory_entries for all to authenticated using(exists(select 1 from profiles p where p.id=auth.uid() and p.store_id=finance_daily_inventory_entries.store_id)) with check(exists(select 1 from profiles p where p.id=auth.uid() and p.store_id=finance_daily_inventory_entries.store_id));
grant select,insert,update on finance_daily_inventory_entries to authenticated;
